import SearchBar from "./SearchBar";
import Filter1 from "./Filter1";
import Filter2 from "./Filter2";
import Filter3 from "./Filter3";

export default function NavBar({paginate}){
    return (
        <div>
             <button onClick={() => window.location.reload()} className={style.button}>Home</button>

             <SearchBar paginate={paginate} />

             <Filter1 paginate={paginate} />

             <Filter2 paginate={paginate} />

             <Filter3 paginate={paginate} />
        </div>
    )
}
